<?php
declare(strict_types=1);
namespace App\Interface\Http\QuestionBank;
use App\Application\Identity\Service\AuthService;use App\Application\QuestionBank\Mapper\PublishedQuestionResponseMapper;use App\Application\QuestionBank\Service\ListDraftQuestionsService;use App\Application\QuestionBank\Service\PublishQuestionService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use App\Infrastructure\Persistence\Doctrine\DoctrineEntityManagerFactory;use App\Infrastructure\Persistence\Doctrine\QuestionBank\DoctrineEditorialQuestionRepository;use App\Infrastructure\Persistence\Doctrine\QuestionBank\DoctrinePublishedQuestionRepository;use App\Interface\Http\Identity\IdentityRequestFactory;use DomainException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;use Slim\App;
final class EditorialQuestionRouteRegistrar {public function __construct(private readonly ApiResponseFactory $responses,private readonly AuthService $auth){}public function register(App $app):void{$em=DoctrineEntityManagerFactory::create();$repo=new DoctrineEditorialQuestionRepository($em,new DoctrinePublishedQuestionRepository($em));$list=new ListDraftQuestionsService($repo,new PublishedQuestionResponseMapper());$publish=new PublishQuestionService($repo);$id=new IdentityRequestFactory();$app->get('/v1/admin/questions/drafts',function(ServerRequestInterface $r,ResponseInterface $p)use($list,$id):ResponseInterface{$u=$this->admin($r,$p,$id);if($u instanceof ResponseInterface)return$u;$q=$r->getQueryParams();$page=max(1,(int)($q['page']??1));$per=min(100,max(1,(int)($q['per_page']??25)));$x=$list->list($page,$per);return$this->responses->paginated($p,$x['items'],(string)$r->getAttribute('request_id'),$x['page'],$x['perPage'],$x['total']);});$app->post('/v1/admin/questions/{id}/publish',function(ServerRequestInterface $r,ResponseInterface $p,array $a)use($publish,$id):ResponseInterface{$u=$this->admin($r,$p,$id);if($u instanceof ResponseInterface)return$u;return$publish->publish((string)$a['id'])?$this->responses->success($p,['id'=>(string)$a['id'],'status'=>'PUBLISHED'],(string)$r->getAttribute('request_id')):$this->responses->problem($p,'STATE_CONFLICT','A questao nao pode ser publicada.',409,(string)$r->getAttribute('request_id'));});}private function admin(ServerRequestInterface $r,ResponseInterface $p,IdentityRequestFactory $i):\App\Application\Identity\DTO\Response\CurrentUserResponseDto|ResponseInterface{try{$u=$this->auth->currentUser($i->accessToken($r));return in_array('ADMIN',$u->roles,true)?$u:$this->responses->problem($p,'FORBIDDEN','Permissao insuficiente.',403,(string)$r->getAttribute('request_id'));}catch(DomainException|UnavailableUserException|\InvalidArgumentException){return$this->responses->problem($p,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$r->getAttribute('request_id'));}}}
